import { mapState } from "vuex";
import { divisionList, divisionFrom, isShowApi, clerkList } from "@/api/agent";
import { formatDate } from "@/utils/validate";
export default {
  name: "agent_extra",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      total: 0,
      total2: 0,
      userLists: [],
      formInline: {
        uid: 0,
        proportion: 0,
        image: "",
      },
      columns: [
        {
          title: "编号",
          key: "id",
          width: 80,
        },
        {
          title: "用户UID",
          key: "uid",
          width: 80,
        },
        {
          title: "代理商名称",
          key: "division_name",
          minWidth: 120,
        },
        {
          title: "代理商电话",
          key: "phone",
          width: 120,
        },
        {
          title: "区域代理名称",
          key: "spread_name",
          minWidth: 80,
        },
        {
          title: "邀请码",
          key: "division_invite",
          width: 80,
        },
        {
          title: "申请时间",
          key: "add_time",
          minWidth: 140,
        },
        {
          title: "申请状态",
          slot: "status",
          width: 100,
        },
        {
          title: "申请图片",
          slot: "images",
          minWidth: 150,
        },
        {
          title: "操作",
          slot: "action",
          width: 160,
        },
      ],
      statusList: [
        {
          status_name: "申请中",
          id: 0,
        },
        {
          status_name: "已同意",
          id: 1,
        },
        {
          status_name: "已拒绝",
          id: 2,
        },
      ],
      FromData: null,
      loading: false,
      current: 0,
      formValidate: {
        page: 1,
        limit: 15,
        keyword: "",
        status: "all",
      },
      staffModal: false,
      clerkReqData: {
        uid: 0,
        page: 1,
        limit: 15,
      },
      clerkLists: [],
    };
  },
  filters: {
    formatDate(time) {
      if (time !== 0) {
        let date = new Date(time * 1000);
        return formatDate(date, "yyyy-MM-dd hh:mm");
      }
    },
  },
  computed: {
    ...mapState("media", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 80;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  mounted() {
    this.getList();
  },
  methods: {
    userSearchs() {
      this.formValidate.page = 1;
      this.getList();
    },
    jump(uid) {
      this.clerkReqData.uid = uid;
      this.getClerkList();
    },
    getClerkList() {
      this.clerkReqData.division_type = 3;
      clerkList(this.clerkReqData).then((res) => {
        this.clerkLists = res.data.list;
        this.total2 = res.data.count;
        this.staffModal = true;
      });
    },
    // 列表
    getList() {
      this.loading = true;
      divisionList(this.formValidate)
        .then(async (res) => {
          let data = res.data;
          this.userLists = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.formValidate.page = index;
      this.getList();
    },
    clerkPageChange() {
      this.clerkReqData.page = index;
      this.getClerkList();
    },
    // 添加表单
    groupAdd(id, type) {
      this.$modalForm(divisionFrom(id, type))
        .then((res) => {
          this.getList();
        })
        .catch((err) => {});
    },
    // 修改是否显示
    onchangeIsShow(row) {
      let data = {
        id: row.uid,
        status: row.division_status,
      };
      isShowApi(data)
        .then(async (res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 编辑
    edit(row) {},
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        method: "DELETE",
        uid: row.id,
        url: `agent/division/apply/del/${row.id}`,
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.userLists.splice(num, 1);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
  },
};
